package com.jnapanam.sportszone.training.dto;import com.jnapanam.sportszone.training.model.TrainingEnrollment;import java.time.Instant;import java.util.UUID;public record EnrollmentResponse(UUID id,UUID batchId,String batchName,UUID userId,String participantName,int participantAge,String status,Instant enrolledAt,Instant cancelledAt){public static EnrollmentResponse from(TrainingEnrollment e){return new EnrollmentResponse(e.getId(),e.getBatch().getId(),e.getBatch().getName(),e.getUser().getId(),e.getParticipantName(),e.getParticipantAge(),e.getStatus().name(),e.getEnrolledAt(),e.getCancelledAt());}}
